const body = req.body as WidgetAddToCartRequest;
const { bundle_id, cart_external_id, selected_variant_external_ids, item_count } = body;

if (!bundle_id) {
  res.status(400).json({ error: "bundle_id required" });
  return;
}
if (!cart_external_id) {
  res.status(400).json({ error: "cart_external_id required" });
  return;
}
if (!Array.isArray(selected_variant_external_ids) || selected_variant_external_ids.length === 0) {
  res.status(400).json({ error: "selected_variant_external_ids must be a non-empty array" });
  return;
}
if (typeof item_count !== "number" || item_count < 1) {
  res.status(400).json({ error: "item_count must be a positive number" });
  return;
}

// Validate variant ids are numeric strings
for (const vid of selected_variant_external_ids) {
  if (typeof vid !== "string" || !/^\d+$/.test(vid)) {
    res.status(400).json({ error: `invalid variant id: ${vid} — must be a numeric string` });
    return;
  }
}

new_string:
const body = req.body as WidgetAddToCartRequest;
const { bundle_id, cart_external_id, selected_variant_external_ids, selected_variant_gids, item_count } = body;

if (!bundle_id) {
  res.status(400).json({ error: "bundle_id required" });
  return;
}
if (!cart_external_id) {
  res.status(400).json({ error: "cart_external_id required" });
  return;
}
if (!Array.isArray(selected_variant_external_ids) || selected_variant_external_ids.length === 0) {
  res.status(400).json({ error: "selected_variant_external_ids must be a non-empty array" });
  return;
}
if (!Array.isArray(selected_variant_gids) || selected_variant_gids.length !== selected_variant_external_ids.length) {
  res.status(400).json({ error: "selected_variant_gids must match selected_variant_external_ids in length" });
  return;
}
if (typeof item_count !== "number" || item_count < 1) {
  res.status(400).json({ error: "item_count must be a positive number" });
  return;
}

// Validate variant ids are numeric strings
for (const vid of selected_variant_external_ids) {
  if (typeof vid !== "string" || !/^\d+$/.test(vid)) {
    res.status(400).json({ error: `invalid variant id: ${vid} — must be a numeric string` });
    return;
  }
}

// Validate variant GIDs are well-formed Shopify GIDs — sourced from live_variant_gid on components
for (const gid of selected_variant_gids) {
  if (typeof gid !== "string" || !gid.startsWith("gid://shopify/ProductVariant/")) {
    res.status(400).json({ error: `invalid variant GID: ${gid} — must be a Shopify ProductVariant GID` });
    return;
  }
}
